function validate([n, edges]) {
  if (!Number.isInteger(n) || n < 1 || n > 50) return 'n is between 1 and 50.';
  if (!Array.isArray(edges) || edges.length > n * (n - 1) / 2) return 'There are at most n * (n - 1) / 2 edges.';
  const seen = new Set();
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 2) return 'Each edge is a pair [a, b].';
    const [a, b] = edge;
    if (![a, b].every(v => Number.isInteger(v) && v >= 0 && v < n)) return 'Edge endpoints are between 0 and n - 1.';
    if (a === b) return 'An edge cannot join a vertex to itself.';
    const key = Math.min(a, b) * 64 + Math.max(a, b);
    if (seen.has(key)) return 'No edge may appear twice.';
    seen.add(key);
  }
  return null;
}

