function countCompleteComponents(n, edges) {
  const adjacent = Array.from({ length: n }, () => new Array(n).fill(false));
  for (const [a, b] of edges) { adjacent[a][b] = true; adjacent[b][a] = true; }
  // Label propagation: every vertex ends with the smallest label it can reach.
  const label = Array.from({ length: n }, (_, i) => i);
  let changed = true;
  while (changed) {
    changed = false;
    for (const [a, b] of edges) {
      const low = Math.min(label[a], label[b]);
      if (label[a] !== low || label[b] !== low) { label[a] = low; label[b] = low; changed = true; }
    }
  }
  let count = 0;
  for (let root = 0; root < n; root++) {
    if (label[root] !== root) continue;
    const members = [];
    for (let v = 0; v < n; v++) if (label[v] === root) members.push(v);
    let ok = true;
    for (const u of members) for (const v of members) if (u !== v && !adjacent[u][v]) ok = false;
    if (ok) count++;
  }
  return count;
}

