function generate(rand, size) {
  const n = size === 'large' ? 40 + Math.floor(rand() * 11) : 1 + Math.floor(rand() * 7);
  const order = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [order[i], order[j]] = [order[j], order[i]]; }
  const edges = [];
  const most = size === 'large' ? 12 : 4;
  let at = 0;
  while (at < n) {
    const group = order.slice(at, at + 1 + Math.floor(rand() * most));
    at += group.length;
    const density = [1, 1, 0.95, 0.7, 0.4][Math.floor(rand() * 5)];
    for (let i = 0; i < group.length; i++)
      for (let j = i + 1; j < group.length; j++)
        if (rand() < density) edges.push(rand() < 0.5 ? [group[i], group[j]] : [group[j], group[i]]);
  }
  // Occasionally link two groups so that a clique gains an outside neighbour.
  if (n > 2 && rand() < 0.3) {
    const a = Math.floor(rand() * n), b = Math.floor(rand() * n);
    if (a !== b && !edges.some(([u, v]) => (u === a && v === b) || (u === b && v === a))) edges.push([a, b]);
  }
  for (let i = edges.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [edges[i], edges[j]] = [edges[j], edges[i]]; }
  return [n, edges];
}
